<?php defined('BASEPATH') OR exit('No direct script access allowed');class Helpdesk extends MY_Controller{private$c;function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c)return;$this->load->model('Helpdesk_model','hd');}function dashboard(){return$this->respond($this->hd->rollup($this->c['organizationId']));}function tickets($id=NULL){$o=$this->c['organizationId'];$m=$this->input->method(TRUE);if($m==='GET'){if($id){$r=$this->hd->detail($o,$id);return$r?$this->respond($r):$this->fail('NOT_FOUND','Ticket not found',404);}return$this->respond($this->hd->tickets($o,array('status'=>$this->input->get('status'),'priority'=>$this->input->get('priority'),'assigneeId'=>$this->input->get('assigneeId'),'q'=>$this->input->get('q'))));}if($m==='DELETE')return$this->hd->remove_ticket($o,$id)?$this->respond(array('deleted'=>TRUE,'id'=>$id)):$this->fail('NOT_FOUND','Ticket not found',404);$d=$this->body();if(!$this->valid($d,!$id))return;$r=$id?$this->hd->update_ticket($o,$id,$this->c['sub'],$d):$this->hd->create($o,$this->c['sub'],$d);return$r?$this->respond($r,$id?200:201):$this->fail('NOT_FOUND','Ticket not found',404);}function assign($id){$d=$this->body();if(!array_key_exists('assigneeId',$d))return$this->fail('VALIDATION_ERROR','assigneeId required',422);$r=$this->hd->assign($this->c['organizationId'],$id,$d['assigneeId']);return$r?$this->respond($r):$this->fail('NOT_FOUND','Ticket not found',404);}function transition($id){$d=$this->body();if(!in_array($d['status']??'',array('new','open','pending','resolved','closed'),TRUE))return$this->fail('VALIDATION_ERROR','Invalid status',422);list($r,$e)=$this->hd->transition($this->c['organizationId'],$id,$d['status']);return$e?$this->fail($e,'Invalid lifecycle transition',409):($r?$this->respond($r):$this->fail('NOT_FOUND','Ticket not found',404));}function comments($id){$o=$this->c['organizationId'];if($this->input->method(TRUE)==='GET')return$this->respond($this->hd->comments($o,$id));$d=$this->body();if(trim($d['authorName']??'')===''||trim($d['body']??'')===''||strlen($d['body'])>4000)return$this->fail('VALIDATION_ERROR','Valid authorName and body required',422);$r=$this->hd->add_comment($o,$id,$this->c['sub'],$d);return$r?$this->respond($r,201):$this->fail('NOT_FOUND','Ticket not found',404);}function comment($id){return$this->hd->remove_comment($this->c['organizationId'],$id)?$this->respond(array('deleted'=>TRUE,'id'=>$id)):$this->fail('NOT_FOUND','Comment not found',404);}private function valid($d,$create){if($create&&(trim($d['subject']??'')===''||trim($d['requesterName']??'')==='')){$this->fail('VALIDATION_ERROR','subject and requesterName required',422);return FALSE;}if(isset($d['status'])&&!in_array($d['status'],array('new','open','pending','resolved','closed'),TRUE)||isset($d['priority'])&&!in_array($d['priority'],array('low','medium','high','urgent'),TRUE)||isset($d['channel'])&&!in_array($d['channel'],array('email','chat','phone','web','other'),TRUE)||isset($d['requesterEmail'])&&$d['requesterEmail']!==NULL&&!filter_var($d['requesterEmail'],FILTER_VALIDATE_EMAIL)){$this->fail('VALIDATION_ERROR','Invalid ticket input',422);return FALSE;}foreach(array('contactId'=>'crm_contacts','companyId'=>'crm_companies')as$k=>$t)if(!empty($d[$k])&&!$this->db->where(array('id'=>$d[$k],'organization_id'=>$this->c['organizationId']))->count_all_results($t)){$this->fail('VALIDATION_ERROR',$k.' not found',422);return FALSE;}return TRUE;}}
